diff --git a/internal/check/comment.go b/internal/check/comment.go
new file mode 100644
index 0000000..bc28b31
--- /dev/null
+++ b/internal/check/comment.go
@@ -0,0 +1,94 @@
+package check
+
+import (
+	"strings"
+
+	"github.com/Xapicc/gh-layer10/internal/fingerprint"
+)
+
+// The comment schema of §7.
+//
+// "The tool does not decide *whether* to comment. It decides what a comment must
+// contain if one is written. Deciding what is worth saying is out of scope."
+
+var commentTypes = []string{TypeComment}
+
+func init() {
+	// §7: the first non-whitespace token is `blocking:`, `non-blocking:` or
+	// `question:`, case-insensitive. Google's `Nit:` convention plus "Don't
+	// block CLs from being submitted based only on personal style preferences";
+	// whether an explicit blocking convention changes duration or outcome is a
+	// question no source found answers.
+	register(Rule{
+		ID: "comment.severity.prefix", Field: "body", Class: Structural, Types: commentTypes,
+		Eval: func(in *Input) Outcome {
+			fields := strings.Fields(string(in.Body))
+			if len(fields) == 0 {
+				return Failed(0, "the comment is empty, and §7 wants it to open with one of %s", strings.Join(severityPrefixes, ", "))
+			}
+			first := strings.ToLower(fields[0])
+			for _, allowed := range severityPrefixes {
+				if first == allowed {
+					return Passed()
+				}
+			}
+			return Failed(in.lineAt(strings.Index(string(in.Body), fields[0])), "the comment opens with %q, and §7's vocabulary is %s", fields[0], strings.Join(severityPrefixes, ", "))
+		},
+	})
+
+	// §7: ≥1 PATHLINE or ≥1 CODESPAN, "as §4.4" — a comment that names nothing
+	// is a comment a later session cannot act on.
+	register(Rule{
+		ID: "comment.concrete", Field: "body", Class: Structural, Types: commentTypes,
+		Eval: func(in *Input) Outcome {
+			if len(in.Doc.CodeSpans) > 0 {
+				return Passed()
+			}
+			for _, line := range in.Doc.Lines {
+				for _, token := range bareTokens(line.Text) {
+					if matchesPathLine(token) {
+						return Passed()
+					}
+				}
+			}
+			return Failed(0, "neither a PATHLINE nor a code span; §7 wants the comment to name what it is about")
+		},
+	})
+
+	// §7: "`comment.fingerprint` | §8.1, required." This is the id §7 gives the
+	// presence rule for a comment, and it is registered instead of
+	// fingerprint.present rather than beside it: the two would decide the same
+	// line, and one defect reported under two ids is what every other rule here
+	// is written to avoid. The rest of §8.1 — the grammar, the word count and
+	// the referential three — runs for a comment under its own ids, because one
+	// fingerprint grammar serves every artefact that carries one.
+	//
+	// Required, and §7 says why: "Comments are the artefact most likely to be
+	// re-posted on every run", which is the class §8.3's confirm step reads a
+	// comment body for.
+	register(Rule{
+		ID: "comment.fingerprint", Field: "body", Class: Structural, Types: commentTypes,
+		Eval: fingerprintRule("comment.fingerprint"),
+	})
+
+	// §13's advisory non-check, with its citation: "The underlying quantity has
+	// never been measured by anyone — nobody has replayed a static analyser over
+	// a corpus of human review comments. Writing a predicate would be inventing
+	// the answer."
+	register(Rule{
+		ID: "comment.mechanical", Field: "body", Class: Advisory, Types: commentTypes,
+		Eval: func(*Input) Outcome {
+			return Skipped("not decided: whether a comment could have been written before reading the code has never been measured, and a predicate would be inventing the answer (§13)")
+		},
+	})
+}
+
+// presenceRuleID is the id an artefact reports §8.1's "exactly one fingerprint,
+// and it is the last non-empty line" under. §7 names the comment's
+// `comment.fingerprint`; everything else uses §8.1's own id.
+func presenceRuleID(artefactType string) string {
+	if artefactType == TypeComment {
+		return "comment.fingerprint"
+	}
+	return fingerprint.RulePresent
+}
diff --git a/internal/check/comment_test.go b/internal/check/comment_test.go
new file mode 100644
index 0000000..763b608
--- /dev/null
+++ b/internal/check/comment_test.go
@@ -0,0 +1,143 @@
+package check
+
+import (
+	"strings"
+	"testing"
+)
+
+// The comment schema of §7.
+
+// minimumViableComment is a comment that passes every §7 rule: one of the three
+// severity prefixes, something named concretely, and the fingerprint §7 makes
+// required because "comments are the artefact most likely to be re-posted on
+// every run".
+const minimumViableComment = "blocking: `src/auth/session.ts:42` still subtracts the skew from the expiry.\n" +
+	"\n" +
+	"<!-- triage-fingerprint: src/auth/session.ts:refreshToken :: tou-ni-re-bi -->\n"
+
+func runComment(t *testing.T, body string, opts Options) Report {
+	t.Helper()
+	return runArtefact(t, TypeComment, []byte(body), opts)
+}
+
+func TestMinimumViableCommentConforms(t *testing.T) {
+	report := runComment(t, minimumViableComment, Options{Version: "0.3.1"})
+	if !report.Conforms {
+		t.Errorf("the §7 comment does not conform:\n%s", report.Human())
+	}
+	for _, check := range report.Checks {
+		if strings.HasPrefix(check.ID, "issue.") || strings.HasPrefix(check.ID, "pr.") || strings.HasPrefix(check.ID, "commit.") {
+			t.Errorf("%s ran against a comment", check.ID)
+		}
+	}
+
+	t.Run("the fingerprint is required and reported under §7's own id", func(t *testing.T) {
+		// §7's table names `comment.fingerprint` and its rule is "§8.1,
+		// required". Registering fingerprint.present beside it would decide the
+		// same line twice and report one defect under two ids.
+		if _, ran := statuses(report)["fingerprint.present"]; ran {
+			t.Error("fingerprint.present ran for a comment as well as comment.fingerprint")
+		}
+		without := runComment(t, "blocking: `src/auth/session.ts:42` still subtracts the skew.\n", Options{})
+		if got := failedIDs(without); strings.Join(got, ",") != "comment.fingerprint" {
+			t.Errorf("a comment with no fingerprint failed %v, want comment.fingerprint", got)
+		}
+	})
+
+	t.Run("the rest of §8.1 still decides the line", func(t *testing.T) {
+		for _, id := range []string{"fingerprint.grammar", "fingerprint.slug.words", "fingerprint.path.exists", "fingerprint.symbol.present"} {
+			if got := statuses(report)[id]; got.Status != Pass {
+				t.Errorf("%s is %s (%q) on a conforming comment", id, got.Status, got.Message)
+			}
+		}
+		// §8.1: a comment carries no ## Evidence and inherits its slug, so the
+		// derivation is skipped with the reason that clause gives.
+		if got := statuses(report)["fingerprint.slug.derived"]; got.Status != Skip || !strings.Contains(got.Message, "evidence unavailable") {
+			t.Errorf("fingerprint.slug.derived is %s (%q), want §8.1's `evidence unavailable`", got.Status, got.Message)
+		}
+		bad := strings.Replace(minimumViableComment, ":: tou-ni-re-bi", ":: tou-ni-re", 1)
+		if got := failedIDs(runComment(t, bad, Options{})); strings.Join(got, ",") != "fingerprint.slug.words" {
+			t.Errorf("a three-word slug in a comment failed %v", got)
+		}
+		absent := strings.Replace(minimumViableComment, "src/auth/session.ts:refreshToken", "src/auth/refresh.ts:refreshFloor", 1)
+		if got := failedIDs(runComment(t, absent, Options{})); strings.Join(got, ",") != "fingerprint.path.exists" {
+			t.Errorf("a comment fingerprinting a path that is not there failed %v", got)
+		}
+	})
+}
+
+func TestCommentSeverityPrefix(t *testing.T) {
+	// §7: "The first non-whitespace token is `blocking:`, `non-blocking:` or
+	// `question:`, case-insensitive." Google's `Nit:` convention, plus "Don't
+	// block CLs from being submitted based only on personal style preferences".
+	// Whether an explicit blocking convention changes duration or outcome: no
+	// source found, which is why the rule is a vocabulary and not a policy.
+	cases := []struct {
+		opening  string
+		wantFail bool
+	}{
+		{"blocking:", false},
+		{"non-blocking:", false},
+		{"question:", false},
+		{"BLOCKING:", false},
+		{"Non-Blocking:", false},
+		{"  question:", false},
+		{"nit:", true},
+		{"blocking", true},
+		{"blocking :", true},
+		{"non-blocking-ish:", true},
+		{"", true},
+	}
+	for _, testCase := range cases {
+		t.Run(testCase.opening, func(t *testing.T) {
+			body := testCase.opening + " `src/auth/session.ts:42` still subtracts the skew.\n\n" +
+				"<!-- triage-fingerprint: src/auth/session.ts:refreshToken :: tou-ni-re-bi -->\n"
+			report := runComment(t, body, Options{})
+			got := statuses(report)["comment.severity.prefix"]
+			switch {
+			case testCase.wantFail && got.Status != Fail:
+				t.Errorf("%q opens a comment and is %s, want fail", testCase.opening, got.Status)
+			case !testCase.wantFail && got.Status != Pass:
+				t.Errorf("%q opens a comment and is %s (%q), want pass", testCase.opening, got.Status, got.Message)
+			}
+		})
+	}
+
+	t.Run("an empty comment fails rather than passing vacuously", func(t *testing.T) {
+		report := runComment(t, "", Options{})
+		if got := statuses(report)["comment.severity.prefix"]; got.Status != Fail {
+			t.Errorf("comment.severity.prefix is %s on an empty comment", got.Status)
+		}
+	})
+}
+
+func TestCommentConcrete(t *testing.T) {
+	// §7: ≥1 PATHLINE or ≥1 CODESPAN, "as §4.4".
+	cases := []struct {
+		why      string
+		text     string
+		wantFail bool
+	}{
+		{"a code span", "blocking: `refreshToken` subtracts the skew twice.", false},
+		{"a bare PATHLINE", "blocking: the skew is subtracted at src/auth/session.ts:42 and again below.", false},
+		{"neither", "blocking: this looks wrong to me and I would change it.", true},
+	}
+	for _, testCase := range cases {
+		t.Run(testCase.why, func(t *testing.T) {
+			body := testCase.text + "\n\n<!-- triage-fingerprint: src/auth/session.ts:refreshToken :: tou-ni-re-bi -->\n"
+			got := statuses(runComment(t, body, Options{}))["comment.concrete"]
+			if testCase.wantFail != (got.Status == Fail) {
+				t.Errorf("comment.concrete is %s (%q)", got.Status, got.Message)
+			}
+		})
+	}
+
+	t.Run("comment.mechanical is reported as a non-check", func(t *testing.T) {
+		// §13: "The underlying quantity has never been measured by anyone …
+		// Writing a predicate would be inventing the answer."
+		got := statuses(runComment(t, minimumViableComment, Options{}))["comment.mechanical"]
+		if got.Status != Skip || !strings.Contains(got.Message, "never been measured") {
+			t.Errorf("comment.mechanical is %s (%q)", got.Status, got.Message)
+		}
+	})
+}
diff --git a/internal/check/common.go b/internal/check/common.go
new file mode 100644
index 0000000..2088a65
--- /dev/null
+++ b/internal/check/common.go
@@ -0,0 +1,179 @@
+package check
+
+import (
+	"strings"
+
+	"github.com/Xapicc/gh-layer10/internal/parse"
+)
+
+// The predicates more than one artefact's schema is written in terms of.
+//
+// §5.2 defines four of the pull request's rules as "as §4.2" and §5.1 defines
+// its title as "same four rules as §4.4", so the two schemas differ in their
+// rows and their ids and not in what they decide. Each constructor below takes
+// the section it reads; the registry entry supplies the id §4.2 or §5.2 assigns
+// it. Writing the predicate twice would be how the pull request's ## Risk
+// quietly stops meaning what ## Blast radius means.
+
+// surfaceRule is §4.2's blast radius row and §5.2's risk row: ≥1 CODESPAN whose
+// content matches PATH, GLOB, or contains a space (a command). §4.3 is the
+// argument — the field is a factual enumeration of surfaces, not a rating.
+func surfaceRule(section string) func(*Input) Outcome {
+	return requiredSection(section, func(in *Input, s parse.Section) Outcome {
+		for _, span := range in.spansIn(s) {
+			if matchesPath(span.Content) || matchesGlob(span.Content) || strings.Contains(span.Content, " ") {
+				return Passed()
+			}
+		}
+		return Failed(s.Line, "no code span here holds a PATH, a GLOB or a command; §4.2 wants named surfaces, not an adjective")
+	})
+}
+
+// scopeFormRule is §4.2's and §5.2's `## Out of scope`: ≥1 bullet; each carries
+// ≥1 CODESPAN and ≥15 non-whitespace characters after the last CODESPAN on that
+// line. The trailing text is the "and why" half of the field — a bare path says
+// what not to touch and not what a fixer would have broken by touching it.
+func scopeFormRule(section string) func(*Input) Outcome {
+	return requiredSection(section, func(in *Input, s parse.Section) Outcome {
+		bullets := bulletLines(in, s)
+		if len(bullets) == 0 {
+			return Failed(s.Line, "no bullet here; §4.2 wants one per surface a fixer should not touch")
+		}
+		spans := in.spansIn(s)
+		for _, bullet := range bullets {
+			onLine := spansOnLine(spans, bullet)
+			if len(onLine) == 0 {
+				return Failed(bullet.Number, "this bullet names nothing in a code span")
+			}
+			last := onLine[len(onLine)-1]
+			trailing := nonWhitespace(in.textAfter(bullet, last.End))
+			if trailing < 15 {
+				return Failed(bullet.Number, "%d non-whitespace characters after the last code span, and §4.2 wants 15; the reason is the field", trailing)
+			}
+		}
+		return Passed()
+	})
+}
+
+// verificationFenceRule is §4.2's "exactly one fence". Two fences is two answers
+// to "what does a future session run", which is the ambiguity §4.5 refuses for a
+// duplicated section.
+func verificationFenceRule(section string) func(*Input) Outcome {
+	return requiredSection(section, func(in *Input, s parse.Section) Outcome {
+		switch fences := in.Doc.FencesIn(s); len(fences) {
+		case 1:
+			return Passed()
+		case 0:
+			return Failed(s.Line, "no fence here; §4.2 wants exactly one holding the command a future session runs")
+		default:
+			return Failed(fences[1].StartLine, "%d fences here; §4.2 wants exactly one", len(fences))
+		}
+	})
+}
+
+// verificationLinesRule is §4.2's "1–5 non-blank lines, each a single command
+// (no blank-line-separated groups)". Never executed — §10 forbids it.
+func verificationLinesRule(section string) func(*Input) Outcome {
+	return requiredSection(section, func(in *Input, s parse.Section) Outcome {
+		fences := in.Doc.FencesIn(s)
+		if len(fences) == 0 {
+			// The fence rule has already failed; deciding this one on a fence
+			// that is not there would report one defect twice.
+			return Skipped("no fence in ## %s to read lines from", section)
+		}
+		lines, interiorBlank := nonBlankLines(fences[0].Content)
+		switch {
+		case len(lines) == 0:
+			return Failed(fences[0].StartLine, "the fence is empty; §4.2 wants 1–5 commands")
+		case len(lines) > 5:
+			return Failed(fences[0].StartLine, "the fence holds %d non-blank lines, and §4.2 allows 1–5", len(lines))
+		case interiorBlank:
+			return Failed(fences[0].StartLine, "a blank line separates two groups of commands, and §4.2 wants one command per line")
+		default:
+			return Passed()
+		}
+	})
+}
+
+// verifyCommandRule is §4.2's opt-in referential check, under --verify-command.
+// §10: the command is resolved and never invoked.
+func verifyCommandRule(section string) func(*Input) Outcome {
+	return optIn("--verify-command", func(in *Input) bool { return in.Opts.VerifyCommand },
+		requiredSection(section, func(in *Input, s parse.Section) Outcome {
+			fences := in.Doc.FencesIn(s)
+			if len(fences) == 0 {
+				return Skipped("no fence in ## %s to read a command from", section)
+			}
+			command, at := firstCommand(in, fences[0])
+			if command == "" {
+				return Skipped("## %s's fence holds no command", section)
+			}
+			if resolvesAsCommand(command, in.Opts.Dir) {
+				return Passed()
+			}
+			return Failed(at, "%q is neither on PATH nor a path that exists", command)
+		}))
+}
+
+// titleLengthRule, titleConcreteRule, titlePunctuationRule and
+// titleImperativeRule are §4.4's four, which §5.1 adopts word for word under
+// `pr.title.*`. All four skip when no --title was given: §11.1 makes the flag
+// optional, and a body checked without a title has no title to be wrong about.
+func titleLengthRule() func(*Input) Outcome {
+	return titleRule(func(title string) Outcome {
+		if n := len([]rune(title)); n > 72 {
+			return Failed(0, "the title is %d characters, and §4.4 allows 72", n)
+		}
+		return Passed()
+	})
+}
+
+// titleConcreteRule's own limits are stated in §4.4: the measured channel is
+// naming a tool or a command, the same paper's direct test of naming paths is
+// null, and the rule is satisfiable by a bare PATH token. It is a cheap
+// constraint against a title that names nothing, kept on that basis.
+func titleConcreteRule() func(*Input) Outcome {
+	return titleRule(func(title string) Outcome {
+		if len(parse.ScanCodeSpans([]byte(title), nil)) > 0 {
